## Why This Is Asked
Tests understanding of a Trie, basic operations, and how to implement autocomplete with limited results.

## Key Concepts
- Trie nodes with children and isEnd
- DFS traversal for autocomplete
- Lexicographic ordering via alphabetical traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.isEnd = false;
  }
}

class Trie {
  constructor() { this.root = new TrieNode(); }
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }
  search(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) return false;
      node = node.children.get(ch);
    }
    return node.isEnd;
  }
  startsWith(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children.has(ch)) return false;
      node = node.children.get(ch);
    }
    return true;
  }
  autocomplete(prefix, limit) {
    let node = this.root; const path = [];
    for (const ch of prefix) {
      if (!node.children.has(ch)) return [];
      node = node.children.get(ch);
      path.push(ch);
    }
    const results = [];
    function dfs(n, acc) {
      if (results.length >= limit) return;
      if (n.isEnd) results.push(prefix + acc.join(''));
      const keys = Array.from(n.children.keys()).sort();
      for (const c of keys) {
        acc.push(c);
        dfs(n.children.get(c), acc);
        acc.pop();
      }
    }
    dfs(node, []);
    return results;
  }
}
```

## Follow-up Questions
- How would you adapt autocomplete to case-insensitive or Unicode inputs?
- What memory optimizations would you apply for very large dictionaries?

## Why This Is Asked
This question tests mastery of three key concepts: Trie mutations (insert/delete), weighted dynamic programming for word break problems, and the ability to implement both iterative and recursive approaches. It also evaluates understanding of handling dynamic dictionary updates and edge cases such as when no valid decomposition exists.

## Key Concepts
- Trie with terminal weights for efficient prefix matching
- Dynamic insert/delete operations on Trie structure
- Weighted word-break DP with O(n × L) complexity where L = maxWordLen
- Both iterative bottom-up DP and memoized top-down DFS variants

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.endWeight = 0;
    this.isEnd = false;
  }
}

class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
    this.maxWordLen = 0;
  }

  insert(word, weight) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
    }
    node.isEnd = true;
    node.endWeight = weight;
    this.maxWordLen = Math.max(this.maxWordLen, word.length);
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) return;
      node = node.children.get(char);
    }
    node.isEnd = false;
    node.endWeight = 0;
  }

  maxPartition(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(-1);
    dp[n] = 0;

    for (let i = n - 1; i >= 0; i--) {
      let node = this.root;
      for (let j = i; j < Math.min(n, i + this.maxWordLen); j++) {
        const char = s[j];
        if (!node.children.has(char)) break;
        node = node.children.get(char);
        if (node.isEnd && dp[j + 1] !== -1) {
          dp[i] = Math.max(dp[i], node.endWeight + dp[j + 1]);
        }
      }
    }
    return dp[0];
  }

  maxPartitionDFS(s, memo = {}) {
    if (s.length === 0) return 0;
    if (s in memo) return memo[s];

    let maxWeight = -1;
    let node = this.root;

    for (let i = 0; i < Math.min(s.length, this.maxWordLen); i++) {
      const char = s[i];
      if (!node.children.has(char)) break;
      node = node.children.get(char);

      if (node.isEnd) {
        const remaining = this.maxPartitionDFS(s.slice(i + 1), memo);
        if (remaining !== -1) {
          maxWeight = Math.max(maxWeight, node.endWeight + remaining);
        }
      }
    }
    memo[s] = maxWeight;
    return maxWeight;
  }
}
```

## Why This Is Asked

Tests ability to translate dependency constraints into a topological order and compute earliest finish times via DP. It also touches complexity and edge cases (cycles).

## Key Concepts

- Topological sort (Kahn or DFS)
- DAG longest path / critical path
- Dynamic programming on DAG
- Time and space complexity

## Code Example

```javascript
function computeProject(durations, edges) {
  const n = durations.length;
  const adj = Array.from({length: n}, () => []);
  const indeg = Array(n).fill(0);
  for (const [u, v] of edges) { adj[u].push(v); indeg[v]++; }
  const est = Array(n).fill(0);
  const finish = Array(n).fill(0);
  const q = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
  let idx = 0;
  while (idx < q.length) {
    const u = q[idx++];
    finish[u] = est[u] + durations[u];
    for (const v of adj[u]) {
      est[v] = Math.max(est[v], finish[u]);
      if (--indeg[v] === 0) q.push(v);
    }
  }
  const project = Math.max(...finish);
  return { finish, project };
}
```

## Follow-up Questions

- How would you detect cycles if the DAG assumption fails? 
- How would you adapt for tasks with minimum and maximum parallelism constraints?

## Why This Is Asked
This tests building a Trie and adding an autocomplete-style suggest method, a common real-world need.

## Key Concepts
- Trie nodes with 26 children; end-of-word markers; storing full word for suggestions
- Lexicographic DFS for deterministic suggestions
- Complexity and memory trade-offs; edge cases like no matches

## Code Example
```javascript
class TrieNode {
  constructor(){ this.children = new Map(); this.isWord=false; this.word=null }
}
class Trie {
  constructor(){ this.root=new TrieNode(); }
  insert(word){ let n=this.root; for (let ch of word){ if(!n.children.has(ch)) n.children.set(ch,new TrieNode()); n=n.children.get(ch); } n.isWord=true; n.word=word; }
  search(word){ let n=this.root; for(let ch of word){ if(!n.children.has(ch)) return false; n=n.children.get(ch); } return n.isWord; }
  startsWith(prefix){ let n=this.root; for(let ch of prefix){ if(!n.children.has(ch)) return false; n=n.children.get(ch); } return true; }
  suggest(prefix, limit){ let n=this.root; for(let ch of prefix){ if(!n.children.has(ch)) return []; n=n.children.get(ch); }
    const res=[];
    const dfs=(cur, path)=>{ if(res.length>=limit) return; if(cur.isWord) res.push(prefix+path); const keys=Array.from(cur.children.keys()).sort(); for(let c of keys){ dfs(cur.children.get(c), path+c); } };
    dfs(n, '');
    return res;
  }
}
```

